Observed Transition Frequencies

trans_table &lt;- dat_model |&gt;
  group_by(trt, y_lag, y) |&gt;
  summarise(n = n(), .groups = "drop") |&gt;
  group_by(trt, y_lag) |&gt;
  mutate(prop = n / sum(n)) |&gt;
  filter(y == 1) |&gt;
